import 'package:dio/dio.dart';import 'package:get_it/get_it.dart';import 'package:gamezone/core/networking/dio_factory.dart';import '../../feature/register/data/repo/register_repo.dart';final GetIt getIt = GetIt.instance;Future<void> setupGetIt() async {  getIt.registerLazySingleton<Dio>(() => DioFactory.getAuthDio());  getIt.registerLazySingleton<RegisterRepo>(() => RegisterRepo(getIt<Dio>()));}